<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from "vue";
import { CheckCircle2, Eye, LoaderCircle, Pencil, Plus, Trash2, WalletCards, X } from "lucide-vue-next";
import ConfirmModal from "@/components/operations/ConfirmModal.vue";
import DataPanel from "@/components/operations/DataPanel.vue";
import OpsModal from "@/components/operations/OpsModal.vue";
import StatusBadge from "@/components/operations/StatusBadge.vue";
import { currentUser } from "@/lib/api";
import { operationsRepository } from "@/data/repositories/operationsRepository";
import type { UiAuditRecord, UiCommissionRecord, UiCommissionRuleRecord, UiInstituteRecord, UiPayoutRecord, UiCatalogRecord } from "@/data/models/operations";

type Tab = "platform-fees" | "institute-earnings" | "commission-rules" | "payouts" | "audit";
const canManageCommissions = computed(() => currentUser()?.roles?.some((role) => role.slug === "system_admin") ?? false); const tabs = computed<Array<{ key: Tab; label: string }>>(() => canManageCommissions.value ? [{ key: "platform-fees", label: "Platform fees" }, { key: "institute-earnings", label: "Institute earnings" }, { key: "commission-rules", label: "Settlement rules" }, { key: "payouts", label: "Earnings payouts" }, { key: "audit", label: "Audit log" }] : [{ key: "audit", label: "Audit log" }]); const tab = ref<Tab>(canManageCommissions.value ? "platform-fees" : "audit");
const loading = ref(false); const saving = ref(false); const deleting = ref(false); const error = ref(""); const rules = ref<UiCommissionRuleRecord[]>([]); const commissions = ref<UiCommissionRecord[]>([]); const payouts = ref<UiPayoutRecord[]>([]); const audits = ref<UiAuditRecord[]>([]); const institutes = ref<UiInstituteRecord[]>([]); const plans = ref<UiCatalogRecord[]>([]);
const selected = ref<number[]>([]); const auditDetail = ref<Record<string, unknown> | null>(null); const editingRule = ref<UiCommissionRuleRecord | null | undefined>(undefined); const deleteRule = ref<UiCommissionRuleRecord | null>(null);
const ruleDefaults = { institute_id: 0, plan_id: 0, commission_type: "percentage", direction: "platform_pays_institute" as "platform_pays_institute" | "platform_collects_from_institute", fixed_amount: "0", percentage: 10, currency: "GBP", is_active: true }; const ruleForm = reactive({ ...ruleDefaults }); const money = (minor: number, currency: string) => new Intl.NumberFormat(undefined, { style: "currency", currency }).format(minor / 100); const selectedRows = computed(() => commissions.value.filter((item) => item.settlementType === "institute_earning" && selected.value.includes(item.id))); const instituteName = (id: number) => institutes.value.find((item) => item.id === id)?.name || `Institute #${id}`;
async function load() { loading.value = true; error.value = ""; selected.value = []; try { if (tab.value === "platform-fees") commissions.value = (await operationsRepository.commissions({ settlement_type: "platform_fee", per_page: 100 })).items; else if (tab.value === "institute-earnings") commissions.value = (await operationsRepository.commissions({ settlement_type: "institute_earning", per_page: 100 })).items; else if (tab.value === "commission-rules") { const [rulePage, institutePage, planPage] = await Promise.all([operationsRepository.commissionRules({ per_page: 100 }), operationsRepository.institutes({ per_page: 100 }), operationsRepository.plans({ per_page: 100 })]); rules.value = rulePage.items; institutes.value = institutePage.items; plans.value = planPage.items; } else if (tab.value === "payouts") payouts.value = (await operationsRepository.payouts({ per_page: 100 })).items; else audits.value = (await operationsRepository.audits({ per_page: 100 })).items; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load governance data."; } finally { loading.value = false; } }
function openRule(item?: UiCommissionRuleRecord) { editingRule.value = item || null; Object.assign(ruleForm, item ? { institute_id: item.instituteId, plan_id: item.planId || 0, commission_type: item.type, direction: item.direction, fixed_amount: String(item.fixedAmountMinor / 100), percentage: item.percentage, currency: item.currency, is_active: item.active } : ruleDefaults); }
async function saveRule() { saving.value = true; const payload = { institute_id: ruleForm.institute_id, plan_id: ruleForm.plan_id || null, commission_type: ruleForm.commission_type, direction: ruleForm.direction, fixed_amount_minor: ruleForm.commission_type === "fixed" ? Math.round(Number(ruleForm.fixed_amount) * 100) : null, percentage: ruleForm.commission_type === "percentage" ? ruleForm.percentage : null, currency: ruleForm.currency, starts_at: null, ends_at: null, is_active: ruleForm.is_active, metadata: {} }; try { if (editingRule.value?.id) await operationsRepository.update("commission-rules", editingRule.value.id, payload); else await operationsRepository.create("commission-rules", payload); editingRule.value = undefined; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to save commission rule."; } finally { saving.value = false; } }
async function removeRule() { if (!deleteRule.value) return; deleting.value = true; try { await operationsRepository.remove("commission-rules", deleteRule.value.id); deleteRule.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to delete commission rule."; } finally { deleting.value = false; } }
async function createPayout() { if (!selectedRows.value.length) return; const instituteIds = new Set(selectedRows.value.map((item) => item.instituteId)); if (instituteIds.size !== 1) { error.value = "Select commissions belonging to one institute per payout."; return; } saving.value = true; try { await operationsRepository.createPayout(selectedRows.value[0].instituteId, selected.value); selected.value = []; tab.value = "payouts"; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to create payout."; } finally { saving.value = false; } }
async function markPaid(id: number) { saving.value = true; try { await operationsRepository.markPayoutPaid(id); await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to mark payout paid."; } finally { saving.value = false; } } async function viewAudit(id: number) { try { auditDetail.value = (await operationsRepository.audit(id)).data; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load audit event."; } } watch(tab, load); onMounted(load);
</script>

<template><div class="space-y-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-[12px] font-semibold uppercase tracking-[0.12em] text-pink">Controls & traceability</p><h2 class="mt-1 text-[26px] font-bold tracking-[-0.035em]">Governance</h2><p class="mt-1 text-[13px] text-ink3">Platform fees, institute earnings, refund reversals and immutable audit visibility.</p></div><button v-if="tab === 'institute-earnings' && selected.length" class="ops-button-primary inline-flex items-center gap-2" :disabled="saving" @click="createPayout"><LoaderCircle v-if="saving" :size="14" class="animate-spin" /><WalletCards v-else :size="15" /> {{ saving ? 'Creating…' : `Create earnings payout (${selected.length})` }}</button><button v-else-if="tab === 'commission-rules'" class="ops-button-primary inline-flex items-center gap-2 transition hover:-translate-y-0.5 hover:shadow-md" @click="openRule()"><Plus :size="15" /> New rule</button></div><p v-if="error" class="rounded-xl bg-pink-light px-4 py-3 text-[13px] text-pink">{{ error }}</p><div class="flex flex-wrap gap-1 rounded-xl border border-border bg-bg-card p-1.5"><button v-for="item in tabs" :key="item.key" class="rounded-lg px-4 py-2 text-[12px] font-semibold transition" :class="tab === item.key ? 'bg-blue text-white shadow-sm' : 'text-ink3 hover:bg-bg-soft'" @click="tab = item.key">{{ item.label }}</button></div>
  <DataPanel v-if="tab === 'platform-fees' || tab === 'institute-earnings'" :title="tab === 'platform-fees' ? 'Platform fee ledger' : 'Institute earnings ledger'" :description="`${commissions.length} records`" :loading="loading" :empty="!commissions.length"><div class="overflow-x-auto"><table class="w-full min-w-[880px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Select</th><th class="px-4 py-3">Institute</th><th class="px-4 py-3">Student user</th><th class="px-4 py-3">Gross</th><th class="px-4 py-3">Reversed</th><th class="px-4 py-3">Net</th><th class="px-5 py-3">Status</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="item in commissions" :key="item.id" class="transition hover:bg-bg-soft/70"><td class="px-5 py-3.5"><input v-if="tab === 'institute-earnings' && item.status === 'pending' && item.netAmountMinor > 0" v-model="selected" type="checkbox" :value="item.id" /><span v-else>—</span></td><td class="px-4 py-3.5 font-semibold">#{{ item.instituteId }}</td><td class="px-4 py-3.5">#{{ item.studentUserId }}</td><td class="px-4 py-3.5">{{ money(item.amountMinor, item.currency) }}</td><td class="px-4 py-3.5 text-pink">{{ money(item.reversedAmountMinor, item.currency) }}</td><td class="px-4 py-3.5 font-semibold">{{ money(item.netAmountMinor, item.currency) }}</td><td class="px-5 py-3.5"><StatusBadge :value="item.status" /></td></tr></tbody></table></div></DataPanel>
  <DataPanel v-else-if="tab === 'commission-rules'" title="Platform fee and institute earning rules" :loading="loading" :empty="!rules.length"><div class="grid gap-4 p-5 md:grid-cols-2 xl:grid-cols-3"><article v-for="item in rules" :key="item.id" class="rounded-2xl border border-border p-4 transition hover:-translate-y-0.5 hover:shadow-md"><div class="flex justify-between"><StatusBadge :value="item.active ? 'active' : 'inactive'" /><div class="flex gap-1"><button class="ops-icon-button" @click="openRule(item)"><Pencil :size="14" /></button><button class="ops-icon-button hover:bg-pink-light hover:text-pink" @click="deleteRule = item"><Trash2 :size="14" /></button></div></div><h3 class="mt-4 text-[14px] font-bold">{{ instituteName(item.instituteId) }}</h3><p class="mt-1 text-[12px] text-ink3">{{ item.direction === 'platform_pays_institute' ? 'Institute earning paid by platform' : 'Platform service fee retained from collection' }}</p><p class="mt-1 text-[12px] capitalize text-ink3">{{ item.type === 'fixed' ? money(item.fixedAmountMinor, item.currency) : `${item.percentage}%` }} per successful payment</p></article></div></DataPanel>
  <DataPanel v-else-if="tab === 'payouts'" title="Institute earnings payouts" :loading="loading" :empty="!payouts.length"><div class="overflow-x-auto"><table class="w-full min-w-[700px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Reference</th><th class="px-4 py-3">Institute</th><th class="px-4 py-3">Amount</th><th class="px-4 py-3">Status</th><th class="px-5 py-3 text-right">Action</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="item in payouts" :key="item.id"><td class="px-5 py-3.5 font-mono font-semibold">{{ item.reference }}</td><td class="px-4 py-3.5">#{{ item.instituteId }}</td><td class="px-4 py-3.5 font-semibold">{{ money(item.amountMinor, item.currency) }}</td><td class="px-4 py-3.5"><StatusBadge :value="item.status" /></td><td class="px-5 py-3.5 text-right"><button v-if="item.status !== 'paid'" :disabled="saving" class="inline-flex items-center gap-1.5 rounded-lg border border-border px-2.5 py-1.5 text-[11px] font-semibold hover:bg-mint-light hover:text-mint disabled:opacity-50" @click="markPaid(item.id)"><CheckCircle2 :size="13" /> Mark paid</button></td></tr></tbody></table></div></DataPanel>
  <DataPanel v-else title="Audit log" :description="`${audits.length} events`" :loading="loading" :empty="!audits.length"><div class="divide-y divide-border"><button v-for="item in audits" :key="item.id" class="grid w-full gap-2 px-5 py-3.5 text-left transition hover:bg-bg-soft sm:grid-cols-[1.2fr_.7fr_.8fr_auto_auto]" @click="viewAudit(item.id)"><p class="text-[12px] font-semibold text-ink">{{ item.action }}</p><p class="text-[11px] text-ink3">Actor {{ item.actorId || 'system' }}</p><p class="text-[11px] text-ink3">{{ item.target || 'System' }}</p><time class="text-[10px] text-ink4">{{ item.createdAt ? new Date(item.createdAt).toLocaleString() : '' }}</time><Eye :size="14" class="text-ink4" /></button></div></DataPanel>
  <OpsModal :open="editingRule !== undefined" max-width="max-w-md" :close-on-backdrop="!saving" @close="editingRule = undefined"><form class="rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="saveRule"><div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">{{ editingRule?.id ? 'Edit' : 'New' }} commission rule</h3><p class="mt-1 text-[12px] text-ink3">Choose whether the platform pays or retains the configured amount.</p></div><button type="button" @click="editingRule = undefined"><X :size="18" /></button></div><div class="space-y-3"><label class="text-[11px] font-semibold">Institute<select v-model.number="ruleForm.institute_id" required class="ops-input"><option :value="0" disabled>Select institute</option><option v-for="item in institutes" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="text-[11px] font-semibold">Plan<select v-model.number="ruleForm.plan_id" class="ops-input"><option :value="0">All plans</option><option v-for="item in plans" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="text-[11px] font-semibold">Settlement direction<select v-model="ruleForm.direction" class="ops-input"><option value="platform_pays_institute">Platform pays institute</option><option value="platform_collects_from_institute">Platform collects/retains from institute</option></select></label><label class="text-[11px] font-semibold">Type<select v-model="ruleForm.commission_type" class="ops-input"><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option></select></label><label v-if="ruleForm.commission_type === 'percentage'" class="text-[11px] font-semibold">Percentage<input v-model.number="ruleForm.percentage" required type="number" min="0" max="100" step="0.01" class="ops-input" /></label><div v-else class="grid grid-cols-2 gap-3"><label class="text-[11px] font-semibold">Amount<input v-model="ruleForm.fixed_amount" required type="number" min="0" step="0.01" class="ops-input" /></label><label class="text-[11px] font-semibold">Currency<input v-model="ruleForm.currency" required maxlength="3" class="ops-input uppercase" /></label></div><label class="flex items-center gap-2 text-[11px] font-semibold"><input v-model="ruleForm.is_active" type="checkbox" /> Active</label></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="ops-button-secondary" @click="editingRule = undefined">Cancel</button><button :disabled="saving" class="ops-button-primary inline-flex min-w-28 items-center justify-center gap-2"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Saving…' : editingRule?.id ? 'Update rule' : 'Create rule' }}</button></div></form></OpsModal>
  <OpsModal :open="Boolean(auditDetail)" max-width="max-w-2xl" @close="auditDetail = null"><div class="max-h-[85vh] overflow-y-auto rounded-2xl border border-border bg-bg-card p-5 shadow-2xl"><div class="mb-4 flex items-start justify-between"><div><h3 class="text-[17px] font-bold">Audit event detail</h3><p class="mt-1 text-[12px] text-ink3">Stored request and change metadata.</p></div><button @click="auditDetail = null"><X :size="18" /></button></div><pre class="overflow-x-auto whitespace-pre-wrap rounded-xl bg-bg-soft p-4 text-[11px] text-ink2">{{ JSON.stringify(auditDetail, null, 2) }}</pre></div></OpsModal>
  <ConfirmModal :open="Boolean(deleteRule)" title="Delete commission rule?" :message="`Remove the rule for ${instituteName(deleteRule?.instituteId || 0)}? Existing earned commissions are not changed.`" confirm-label="Delete rule" :busy="deleting" @close="deleteRule = null" @confirm="removeRule" />
</div></template>
